latitude = -30.0, retrograde = False, northward = 5.0, cools = True
@pytest.mark.parametrize('latitude,retrograde,northward,cools', [ (30., False, -5., True), (30., True, 5., True), (-30., False, 5., True), (-30., True, -5., True), (30., False, 5., False), (30., True, -5., False), (-30., False, -5., False), (-30., True, 5., False), (0., False, -5., False), (0., True, 5., False), ]) def test_west_coast_surface_responds_to_signed_coriolis(latitude, retrograde, northward, cools): grid = _toy_case().grid grid.land[:] = False grid.land[:, 15:] = True # west coast: offshore is west grid.land_frac[:] = grid.land grid.elev[:] = 0. grid.elev_max[:] = 0. grid.lat[:] = latitude m = ClimateModel(strict_params().replace(upwelling=4., retrograde=retrograde), grid=grid) # Prescribe a constant known wind and20C uncoupled sea to isolate the first # production SST step. Stop at its existing diagnostic tap BEFORE any heat # or moisture solve. These are ten source snapshots, not climate reruns. zeros = np.zeros_like(grid.lat) m.zonal_wind = lambda season:(zeros, np.full_like(zeros, northward), zeros, zeros) m.sst = lambda day, zonal_sea, land:np.full_like(zeros, 20.) surface = [] def capture(stage, day, value): if stage == 'sst': surface.append(value.copy()) raise SurfaceCaptured m.tap = capture with pytest.raises(SurfaceCaptured): m.run() near = m.upwelling_weight > .5 assert near.any() if cools: > assert surface[0][near].mean() < 19. E assert np.float64(20.0) < 19.0 E + where np.float64(20.0) = <built-in method mean of numpy.ndarray object at 0x7f2d4cf4a310>() E + where <built-in method mean of numpy.ndarray object at 0x7f2d4cf4a310> = array([20., 20., 20., 20., 20., 20., 20., 20., 20., 20., 20., 20., 20.,\n 20., 20., 20., 20., 20., 20., 20., 20., 20., 20., 20.]).mean
